insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2025-11-10' limit 1),'report',1,'Lily Strange - Internal Chair','QOTW: fresh linen because I have always yearned to eat a tide pod THANK YOU to all who tabled with me at parents’ and family weekend, we resulted in many parents haggling their children to get involved YAY Requisition form tutorial → in the CoC 2025-26 folder We need to pass $1053.60 for the UCEN reservations for the chair meetings… BUDGET!!!!!!! Sooooo….. THIS IS OKAY. We knew we would have to request more funding anyway 😝 … turns out our budget is not enough to cover honoraria even :( Tablecloth…we have a plain white one for now (THANK YOU YESHUA) Should we just hold off until next quarter / when we figure out the budget? Let’s brainstorm some supplies we can use for tabling going forward though! Hopefully we get a budget increase and can order some things in time for winter Tablecloth (we can get an exact price but ~$150?) I’m going to do one last search of the computer room… couldn’t get in last time I did check high and low in the senate room though Stickers! Let’s do cute raccoon AS ones and CoC ones Flyers (and plastic stands like Yeshua let us borrow last weekend) Snacks? Got an application for the OSA position… my b! Closed that on the website and emailed the applicant to apply to the pro temp positions How is pub going for this?... we haven’t had many (any?) applicants ☹️ Can we get a IG post ASAP Who have we emailed so far Is anyone available to table with Le Anh at coffee with the Pres (next ones are Nov 18th 2pm-4pm and Dec 2nd 2pm-4pm) To advertise positions in general! Oliver - Nov 18th Shuyi - Dec 2nd Assuming this is next Tues 12:30-1:30pm, who can go? Sophia Layla Oliver This is probably enough! Here are CoC’s slides Reminder for everyone that the AS ONE makeup attendance is due THIS FRIDAY (11/14). Please complete for full honoraria! Our quarterly rep');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2025-11-10' limit 1),'report',2,'Shuyi Sum - Vice Chair','QOTW: Biscoff cookies + earl grey tea (in my grandma era) Emailed Samrita about OSA rejection and Office of Senate positions 1 application for OOS ! Can’t make it to quarterly reports or TSC tabling 🙁 Table with Le Anh at coffee with the Pres Dec 2nd I can compile a list of all applicants + interviews for report');
