insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2025-11-10' limit 1),'report',4,'Layla Hakim - Outreach and Recruitment Coordinators','QOTW: Pine trees!! Tabled at the chancellor’s fair, feel like it went pretty well! Plus a little feature on our insta story🤩 Emailed advisors about the open senate positions with my proposed email draft, waiting to hear back Planning to table for the TSC event…waiting to get my work schedule though If I can go I will update the fliers I made and print more out to have at our table');
