insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2025-11-24' limit 1),'report',5,'Layla Hakim - Outreach and Recruitment Coordinators','QOTW: Make the most out of my last two quarters! Sent out emails for the Senate Outreach Committee, no responses yet Mira, do you have a post for our insta? Polisci is asking for a flyer for them to post again Presented at the transfer event, it went well! Side note the new transfer center is adorable Making the email about the book bank, almost complete Savanah did they say they wanted us to advertise their services only, or also their volunteer positions? Im including most of their info on the email but did they say anything specific they wanted us to include? Heres a link to my draft if anyone wants to check it out: https://docs.google.com/document/d/1yaJb0Dm8kk5schg-FDByTFYAWGjOi3rmVu4-9ufICWQ/edit?tab=t.0 Whats best to do over the break for outreach? Any suggestions?');
