insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2025-09-29' limit 1),'report',1,'Lily Strange - Internal Chair','QOTW: Getting students involved in AS! My priority this year is to build a strong team and keep an organized list of openings for students looking to apply. I am new to CoC! Hi everyone and welcome!! Please familiarize yourself with the drive and your officer duties if you haven’t already. Sophia, Yeshua, and I have been working on a few hirings and just wrapped up the Recreation Center Governance Board and the AS Living History Project, thank you guys! 🎉 All current hirings are on this CoC Open Positions spreadsheet, although CoC is not currently responsible for interviewing anyone currently on there, but we have a few loose ends to wrap up We are going to interview soon for two vacant positions on our board, one O&R and one Internal Liaison Please forward your office hours to Shuyi by the end of the week For O&R, your office hours will be applied to BCU Outreach. Please attend one BCU meeting a week (excluding week 1, 10, and finals), times and locations will be on this spreadsheet. Please log your meetings on this spreadsheet to prevent overlap. For Internal Liaisons, please check up on all current hirings on the open position spreadsheet so we know when to close positions on the website, or when BCU chairs require support. Shuyi- I saw you started a spreadsheet for CoC applications, amazing, I will give you more info on which are filled Does everyone have access to slack, and their emails? I need to transfer the two factor authentication numbers over.');
