insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',1,'Lily Strange - Internal Chair','QOTW: That weird hailstorm last year (?) ..but I will be in the snow next week 😋 Budget update → ledger Please update with your requisition amount after submitting Liaison committee hiring → in the upcoming week(s) AS Olympics (AKA SQUID GAMES) Planning brainstorm: Bouncy house obstacle course IV drip cookies, star, triangle, etc Raffle gift cards Free lunch/dinner Tug of war Red light green light Anyone want to take lead on the legal code bill for this? Oliver UCSB Career Center update! Ideas!? Voting to resign and appoint Mailing a list of students… can someone directly connect them to all external forms taking applications + email if interested in office of senate leadership Layla Retreat - Monday Feb 9th Location TBD Arnoldi’s Cafe');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',2,'Sophia Fei - External Chair','Qotw: last year i went skiing in big bear Coc budget?? Fill out 3 requisitions (chilis, costco, target) - do i fill out the pdf or do the online survey sent out??? Interviewed for OSA and OSL I am now AUTHORIZED 😎 🔥- Shuyi PLAN RETREAT THIS WEEEEK Pass money for last quarter retreat…');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',3,'Shuyi Sum - Vice Chair','QOTW: ~2ish years ago in Lake Tahoe ! Interviewed Baleigh for OSL 👍 Eemaan/Liaison Committee email/scheduling support - noted 👍 Tabling w Le Anh - signups WEDNESDAYS 10AM-11AM OR 11AM-12PM 2/11: Oliver Ramirez Carrera (10-11AM) 2/25: Yeshua Valdez Rodriguez (10-11 am) 3/11: Brunch retreat still tbd ?');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',4,'Oliver Ramirez Carrera - Internal Liaison','QOTW: This last winter break Sent out an email reminding BCUs to fill out the recruitment spreadsheet Interviewed w/ Shuyi and Rylee regarding the office of senate leadership position Also had a Campus Elections Committee meeting this past Tuesday, it was the first meeting of the quarter Talked about voter language, make small changes to ensure language is understood I can do coffee w/ the president 2/11 from 10-11am I can also take lead on the legal code bill for the AS Squid Games');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',5,'Layla Hakim - Outreach and Recruitment Coordinators','QOTW: this winter break at my grandparents house in NY Sent out emails promoting open positions for I think the last four BCUs on the open positions spreadsheet, a lot of departments sent them out this time I think Made new fliers for these positions as well, can adjust them accordingly if any positions are filled Working on making an event, but have a few questions Vision board event magazines? Valentine''s card making maybe instead? How would we relate this to AS though Maybe bouquet making?');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',6,'Yeshua Valdez Rodriguez - Outreach and Recruitment Coordinators','QOTW: Last time I saw snow was last year’s winter break, where I went to the sequoias with a few friends Website Update The website is still under development Alex had to meet with Sean given the old code, and ran into some problems during winter break He said that the final draft should be ready in a week or two, and he’ll send it over as soon as it’s done');
