insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-01-26' limit 1),'report',8,'Archish Prakhya - Pearman Fellow','QOTW: The last time I saw snow was during a visit to Chicago last winter to attend an orchestra concert for my sister Attended the Pearman Fellowship Group Meet with other internal Pearman fellows today and brainstorming ideas for the final Pearman Fellow Final Project. Schedule time to shadow interview events throughout and schedule coffee time!');
