insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-02-02' limit 1),'report',6,'Layla Hakim - Outreach and Recruitment Coordinators','QOTW: only having one final exam to study for🙏 Savanah and I have been working on our event and its almost all set to go! 11-12:45 in pardall on the 11th please come! Added the flier to the promotional folder in the drive It’s probably going to just be a more chill outreach event but we’ll have fliers with open positions out on the table and we’ll speak a bit about CoC Going to post on the insta with the flier tonight Ordered supplies from amazon - is there a specific time I should put in a requisition request? Also how would I go about this without a physical receipt - would a screenshot work? Also do we have a specific budget for it?');
