insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-02-23' limit 1),'report',6,'Layla Hakim - Outreach and Recruitment Coordinators','QOTW: my balcony or the path near sea lookout park Filled out self-eval form I dont think we had a meeting after my event yet soo: Savanah and i did our event, we make posters for it and put it around the school and on ig We had a good event! I think around 15 people showed up and a group of 6 stayed the whole time which was great and they said they had a great time🙏 I posted about it on the instagram story too Near the end i told them about AS, what CoC does, how to get involved, open positions, etc I had fliers about open positions that I had on the table and a few people were interested and took pictures! We did spend around 50 total for this so we need to do requisitions - how do I do this and do I need to fill out a form or add my receipt anywhere? I’ve never done it so I don’t know Since this is done what else should I work on? I can send more emails or do something on instagram but it doesn’t look like the spreadsheet has changed much Still need to do training');
