insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-04-29' limit 1),'report',1,'Lily Strange - Internal Chair','QOTW: Filling the board for Jewish Commission Application form here: Because we are filling an entire board, it’s easier to just do google form and see all applicants in one place.. Sorry website lol Can we get this on IG + email lists You can just directly provide the link to the google form, no need to direct to our website and then the form Update on last week Emailing a summary of open positions every month Vincent Ton would like to meet and discuss workflow for tracking resignations & appointments next year. Mira and Oliver, do you want to coordinate with me to set a meeting time? Website Mira and Oliver, do you have website access? SOP We can send an email for all open positions now, I just closed positions for people who never replied LOL we can assume they are closed so the website is up to date! Rollover due soon, do we want to request any? We have ~1.6k left in our budget RETREAT NEXT WEEK Are people down for a potluck? If that’s too hard to do timing wise, no worries we can just do pizza 5pm next Wednesday (same as meeting time) Paper plate awards Looking ahead to the end of the year… a heads up on what is expected for transition materials By week 7 meeting please submit transition reports (meeting after retreat) This includes your email log in, your phone number (to coordinate recovery phone number / log in) Outreach… don’t worry about this. We will make new emails for each outreach next year The projects you have done, steps for doing things (ie, chairs meeting), if you are outreach and your current role isn''t the same as next years, feel free to include any ideas You can use your report from last year as a base, but please add your ideas and perspective as well Submit in CoC → start here (transition materials) You don’t need a sub folder just dump it in th');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-04-29' limit 1),'report',2,'Shuyi Sum - External Chair','QOTW: Will be interviewing CoC candidate tmrw w/ Savanah Will send out zoom link tmrw morning Also helping update positions on website (EAB, CAB) Already have a transition doc for VC but I can also make one for EC Down for potluck !');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-04-29' limit 1),'report',3,'Oliver Ramirez Carrera - Vice Chair','QOTW: A teddy bear hamster, they look very kind No major updates this week I can work on updating the website, saw the document you linked Lily, so thank you I’m guessing I update it according to the spreadsheet? Yes, I’d like to meet with Vincent Ton, keep me updated on that I’m also down for a potluck And let me know if you guys need any help!');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-04-29' limit 1),'report',4,'Layla Hakim - Outreach and Recruitment Careers Coordinator','QOTW: Sent emails for CoC open positions to some departments Only one response so far from History Created draft email for all open AS positions, can send out if needed Send mass email - look for instructions on slides Trans & Queer Commission reached out about their open positions Asked for them to be added to the website (who’s in charge and can edit?) Also want us to email and promote on IG They have an IG post for it, just waiting for the positions to be added to the website before I post it Going to make fliers for Applying+Free food event, make flier for each BCU with open positions to have out, and one w/ a QR code to website Pass down / transition report - need to do Do for new O&R position Put in transition folder in CoC folder Mass email instructions: https://www.canva.com/design/DAHFp1Vu384/lKHtFd-BYflWpxrTvcBcPg/edit?ui=eyJEIjp7IlAiOnsiQiI6ZmFsc2V9fX0 Can just list a few BCUs, dont list all and don’t list positions, just direct to website and emphasize the PAID opportunities Legal code: https://docs.google.com/document/d/1Fx0-10nT9BzaCWmhfDRBy99Qf2Tb-A04YJgsUDvai2U/edit?tab=t.0#heading=h.j5lxqpajeufh');
