insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-05-13' limit 1),'report',1,'Lily Strange - Internal Chair','QOTW: CHAPSTICK and my charger Filled out the honoraria form for everyone! Hopefully we should be getting those soon. State of the Association this next Tuesday 5:30-8pm (usually wraps up around 7) free dinner. I’ll be there, RSVP if you wish RSVP Who is available to help update the website? We have a some more AS orgs to add: Office of the Controller IVCRC Coastal fund and Bike Committee (??? didn''t attach forms, we need to find them) Can we get an email out to all chairs currently with positions opened (all on the spreadsheet that are not green minus these we need to add) if they are still open Budget update! We got much more budget for next year I did not request rollover this year, so let’s please do our best to spend the remaining (~600 ish, will recalculate with less honoraria for spring) A reminder that completed pass down reports were due this meeting I forgot to send a reminder about this, so if you need to submit by tomorrow that’s totally fine Here is the template again Event tm !!!! THANK YOU MIRAAA Yerbs week 10 power up your resume');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-05-13' limit 1),'report',2,'Shuyi Sum - External Chair','QOTW: laptop charger and chewing gum Interviewed Becky w/ Layla and Savanah, see Becky O&R Careers Coordinator Interview Set up two other interviews this week Need to deliberate Thomas, Becky, Kristin State of the Association I have work until 7pm, could make it to the later half if needed Finished transition docs External Chair Overview of Duties Vice Chair Overview of Duties Tasks: Send acceptance email to Thomas for Internal Chair Send acceptance email to Kristin for Internal Liaison Send rejection email to Becky for O&R Careers Coordinator');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-05-13' limit 1),'report',3,'Oliver Ramirez Carrera - Vice Chair','QOTW: My laptop! Interviewed Thomas w/ Shuyi and Savanah Interviewed Kristin w/ Layla and Savanah In contact with Leah in regards to publishing the CoC website on its own bulk mail request Been updating BCUs positions on the CoC website; looking at their Instagram to see if they’re hiring CEC duties finally over Tasks: Need to do template, will finish by tonight! Coastal fund and Bike Committee (??? didn''t attach forms, we need to find them) Can we get an email out to all chairs currently with positions opened (all on the spreadsheet that are not green minus these we need to add) if they are still open Send out email regarding interview tomorrow Text Yoyo about making a design for CoC');
insert into minute_item(meeting_id,section,ordinal,heading,body) values ((select id from meeting where meeting_date='2026-05-13' limit 1),'report',4,'Layla Hakim - Outreach and Recruitment Careers Coordinator','QOTW: aquafor Interviewed Kristin with Savanah and Oliver Interviewed Becky with Shuyi and Savanah Made fliers for tomorrow’s event, sadly I can’t make it but hopefully the fliers are good They’re based on our website, so idk how updated it is but hopefully its accurate Added to the drive!');
